export const storeLabel=name=>/^tienda 2$/i.test(String(name).trim())?'Tienda chica':name;
export function pickStore(stores,shifts,userId,saved){
 const ids=new Set(stores.map(s=>s.id));
 if(ids.has(saved))return saved;
 return shifts.find(s=>s.status==='open'&&s.responsible_id===userId&&ids.has(s.store_id))?.store_id
  ||shifts.find(s=>s.status==='open'&&ids.has(s.store_id))?.store_id||stores[0]?.id||'';
}
export function mergeShifts(recent,open){return [...open,...recent.filter(s=>s.status!=='open'&&!open.some(x=>x.id===s.id))];}
export function formDrafts(root){const drafts=[...root.querySelectorAll('form[data-form]:not([data-form=final_counts])')].map(form=>({action:form.dataset.form,id:form.dataset.id||'',request:form.dataset.request,payload:form.dataset.payload,fields:[...form.elements].filter(e=>e.name&&!e.hasAttribute('data-live-close-value')).map(e=>e.type==='file'||e.type==='password'?{name:e.name,node:e}:{name:e.name,value:e.value,checked:e.checked})}));drafts.panels=[...root.querySelectorAll('#order-detail:not([hidden]),#receipt')];const focused=document.activeElement;if(root.contains(focused)&&focused.matches('input,textarea'))drafts.focus={name:focused.name,action:focused.closest('form')?.dataset.form,search:focused.hasAttribute('data-sale-search'),start:focused.selectionStart,end:focused.selectionEnd};return drafts;}
export function restoreDrafts(root,drafts){for(const panel of drafts.panels||[])root.querySelector('#'+panel.id)?.replaceWith(panel);for(const d of drafts){const form=[...root.querySelectorAll('form[data-form]')].find(f=>f.dataset.form===d.action&&(f.dataset.id||'')===d.id);if(!form)continue;if(d.request)form.dataset.request=d.request;if(d.payload)form.dataset.payload=d.payload;for(const v of d.fields){const e=form.elements.namedItem(v.name);if(!e||e instanceof RadioNodeList)continue;if(v.node){e.replaceWith(v.node);continue;}e.value=v.value;if(e.type==='checkbox')e.checked=v.checked;}}const f=drafts.focus;if(f){const input=f.search?root.querySelector('[data-sale-search]'):[...root.querySelectorAll('form[data-form]')].find(x=>x.dataset.form===f.action)?.elements.namedItem(f.name);if(input?.focus){input.focus({preventScroll:true});try{input.setSelectionRange(f.start,f.end);}catch{}}}}
